def normalizedPairBlock (s : ℕ → X) (p q : ℕ → ℕ) (n : ℕ) : ℕ →₀ ℂ :=
  Finsupp.single (p n) (‖s (p n) - s (q n)‖ : ℂ)⁻¹ -
    Finsupp.single (q n) (‖s (p n) - s (q n)‖ : ℂ)⁻¹

